// Re-match for the five THESIS-WATCH flags raised 2026-09-10 18:45 IST. ALL validation happens here,
// before any write. Any surprise -> throw, nothing is written.
function s(v){return String(v==null?'':v).trim();}
function nz(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
const trk=$('Read Deal Tracker').all().map(i=>i.json);
const inv=$('Read INVESTORS').all().map(i=>i.json);
const st=$('Read STARTUPS').all().map(i=>i.json);
const pipe=$('Read PIPELINE').all().map(i=>i.json);
const el=$('Read ERROR LOG').all().map(i=>i.json);
if(pipe.length<500){throw new Error('ABORT: PIPELINE only '+pipe.length+' rows');}
if(pipe.length<3700){throw new Error('ABORT: PIPELINE '+pipe.length+' rows, expected about 3783');}
if(inv.length<150){throw new Error('ABORT: INVESTORS only '+inv.length+' rows');}
if(st.length<50){throw new Error('ABORT: STARTUPS only '+st.length+' rows');}
if(el.length<2500){throw new Error('ABORT: ERROR LOG only '+el.length+' rows');}

// ---- Deal Tracker must be complete ----
const tcols=Object.keys(trk[0]||{});
let cInv=null;const cDeals=[];
for(const c of tcols){const l=c.toLowerCase();
  if(!cInv&&(l.indexOf('investor')>=0||l.indexOf('vc name')>=0)){cInv=c;}
  if(l.indexOf('deals shared')>=0||l.indexOf('latest deal')>=0||l.indexOf('picked')>=0){cDeals.push(c);}}
if(!cInv||cDeals.length!==3){throw new Error('ABORT: tracker deal columns not found: '+JSON.stringify(tcols));}
const dist={};for(const r of trk){const k=nz(r[cInv]);if(k){dist[k]=1;}}
const nDist=Object.keys(dist).length;
if(trk.length<240||nDist<235){throw new Error('ABORT: Deal Tracker looks truncated - '+trk.length+' rows / '+nDist+' investors (expected ~247 / 240+)');}
// tracker investor names carry suffixes ('Blinc Invest(New)', 'Prath Ventures(Satvik)') - match by prefix
function trkBlob(prefix){let b='';for(const r of trk){if(nz(r[cInv]).indexOf(prefix)!==0){continue;}for(const c of cDeals){b+=' '+s(r[c]);}}return nz(b);}
const TX=[['dsgconsumer','DSG Consumer Partners',["Sugar's Daddy",'LUSTR','Luxova','Healthy Master']],
  ['prathventur','Prath Ventures',["Sugar's Daddy",'LUSTR','Healthy Master','My Soul']],
  ['sianacapital','Siana Capital',['EosNox']],
  ['blincinvest','Blinc Invest',['YUNO','LearningPad','SkillBytes']]];
const trkExcluded=[];
for(const t of TX){const b=trkBlob(t[0]);for(const su of t[2]){if(b.indexOf(nz(su))>=0){trkExcluded.push(t[1]+' x '+su);}}}
// deletions justified ONLY by the tracker must be confirmed by it right now
const MUST=['Blinc Invest x YUNO','Blinc Invest x LearningPad','Blinc Invest x SkillBytes','Prath Ventures x My Soul','Prath Ventures x Healthy Master'];
for(const m of MUST){if(trkExcluded.indexOf(m)<0){throw new Error('ABORT: tracker no longer shows '+m+' - duplicate deletion not justified');}}

// ---- PIPELINE targets ----
const DEL=[
 ['D03426','Riceberg Ventures','RECEX'],['D03473','Riceberg Ventures','Lex Protector'],['D03549','Riceberg Ventures','SureChain'],
 ['D03604','Riceberg Ventures','Vilva AI'],['D03612','Riceberg Ventures','Bon Cuisine'],['D03618','Riceberg Ventures','EosNox'],
 ['D03620','Riceberg Ventures','Fuski.AI'],['D03633','Riceberg Ventures','MonitorExam'],['D03669','Riceberg Ventures','GroCliq'],
 ['D03705','Riceberg Ventures','CLIKD'],['D03715','Riceberg Ventures','HYRGPT'],['D03730','Riceberg Ventures','Road Athena'],
 ['D03733','Riceberg Ventures','Spintly'],['D03764','Riceberg Ventures','MentorCloud'],['D03768','Riceberg Ventures','Opulytics'],
 ['D03800','Riceberg Ventures','LearningPad'],['D03845','Riceberg Ventures','Orbit AI'],['D03853','Riceberg Ventures','Talent Recruit'],
 ['D03882','Riceberg Ventures','SkillBytes'],['D03884','Riceberg Ventures','Springbase.ai'],['D03904','Riceberg Ventures','MindWox'],
 ['D03609','Siana Capital','AI Signal Labs'],['D03653','Siana Capital','YUNO'],['D03666','Siana Capital','Fuski.AI'],
 ['D03714','Siana Capital','GroCliq'],['D03758','Siana Capital','HYRGPT'],['D03802','Siana Capital','MentorCloud'],
 ['D03838','Siana Capital','LearningPad'],['D03878','Siana Capital','Orbit AI'],['D03885','Siana Capital','Talent Recruit'],
 ['D03912','Siana Capital','SkillBytes'],['D04062','Siana Capital','Healthy Master'],['D04121','Siana Capital','Sahaj'],
 ['D03066','DSG Consumer Partners','Orbo AI'],['D03068','DSG Consumer Partners','SureChain'],['D00941','DSG Consumer Partners','Fydo'],
 ['D03445','Blinc Invest','YUNO'],['D03472','Blinc Invest','LearningPad'],['D03544','Blinc Invest','SkillBytes'],
 ['D01189','Blinc Invest','Vira Jal'],['D00419','Blinc Invest','Bon Cuisine'],
 ['D00510','Prath Ventures','Bon Cuisine'],['D01214','Prath Ventures','Spintly'],['D01550','Prath Ventures','Vira Jal'],
 ['D02346','Prath Ventures','Xproguard'],['D02893','Prath Ventures','My Soul'],['D03909','Prath Ventures','Orbo AI'],
 ['D04025','Prath Ventures','Healthy Master'],['D04088','Prath Ventures','Sahaj']];
const PAU=[['D00163','DSG Consumer Partners','Bon Cuisine','B2B corporate-cafeteria business; DSG invests only in B2C propositions'],
 ['D00108','Blinc Invest','LUSTR','luxury-jewellery D2C; outside Blinc mandate (AI, EdTech, FinTech, HRTech, SaaS)']];
const EM=[['D00340','Prath Ventures','VOLD Energy'],['D01008','Prath Ventures','Chayan Karo'],['D01075','Prath Ventures','Fydo'],
 ['D03169','Prath Ventures','Washtro'],['D03700','Prath Ventures','bezgoFresh'],['D03902','Prath Ventures','Luxova']];
const KEEP=['D01284','D01498','D00877','D02877','D03062','D03069','D00878','D00914','D01018','D01077','D01254','D01269','D02254'];
if(DEL.length!==49||PAU.length!==2||EM.length!==6){throw new Error('ABORT: target list sizes changed');}

const byId={};for(const p of pipe){const id=s(p.deal_id);if(!id){continue;}(byId[id]=byId[id]||[]).push(p);}
function one(id,invName,su){const h=byId[id]||[];if(h.length!==1){throw new Error('ABORT: '+id+' resolves to '+h.length+' rows');}
  const r=h[0];if(s(r.investor)!==invName){throw new Error('ABORT: '+id+' is '+s(r.investor)+', expected '+invName);}
  if(nz(r.startup)!==nz(su)){throw new Error('ABORT: '+id+' is '+s(r.startup)+', expected '+su);}
  if(!r.row_number||Number(r.row_number)<2){throw new Error('ABORT: bad row_number for '+id);}return r;}
const seen={};function once(id){if(seen[id]){throw new Error('ABORT: '+id+' targeted twice');}seen[id]=1;}

const delItems=[];
for(const d of DEL){once(d[0]);const r=one(d[0],d[1],d[2]);
  if(s(r.deal_shared).toLowerCase()==='yes'){throw new Error('ABORT: '+d[0]+' has deal_shared=Yes - refusing to delete');}
  if(s(r.investor_response)!==''){throw new Error('ABORT: '+d[0]+' has an investor_response');}
  if(s(r.thread_id)!==''){throw new Error('ABORT: '+d[0]+' has a thread_id');}
  delItems.push({row_number:Number(r.row_number),deal_id:d[0],investor:d[1],startup:s(r.startup)});}
delItems.sort((a,b)=>b.row_number-a.row_number);
for(let i=1;i<delItems.length;i++){if(delItems[i].row_number===delItems[i-1].row_number){throw new Error('ABORT: duplicate row_number');}}

const pauseItems=[];
for(const p of PAU){once(p[0]);const r=one(p[0],p[1],p[2]);
  if(s(r.deal_shared).toLowerCase()!=='yes'){throw new Error('ABORT: '+p[0]+' is not a sent row');}
  if(s(r.investor_response)!==''){throw new Error('ABORT: '+p[0]+' has a response - leave alone');}
  if(s(r.pause)!==''){throw new Error('ABORT: '+p[0]+' already paused');}
  const prev=s(r.notes);
  pauseItems.push({deal_id:p[0],pause:'Yes',next_action:'Stopped - off updated mandate',notes:(prev?prev+' | ':'')+'Follow-ups stopped 2026-09-10 (re-match): '+p[3]});}

const emailItems=[];
for(const e of EM){once(e[0]);const r=one(e[0],e[1],e[2]);
  if(s(r.deal_shared).toLowerCase()==='yes'){throw new Error('ABORT: '+e[0]+' already sent - keep its address');}
  if(s(r.investor_response)!==''){throw new Error('ABORT: '+e[0]+' has a response');}
  if(s(r.email).toLowerCase()!=='ria@prathventures.com'){throw new Error('ABORT: '+e[0]+' email is '+s(r.email));}
  emailItems.push({deal_id:e[0],email:'ashna@prathventures.com'});}
for(const k of KEEP){once(k);}

// every unsent row of the five investors must be accounted for (delete / re-point / deliberate keep)
const FIVE=['Riceberg Ventures','Siana Capital','DSG Consumer Partners','Blinc Invest','Prath Ventures'];
for(const p of pipe){if(FIVE.indexOf(s(p.investor))<0){continue;}if(s(p.deal_shared).toLowerCase()==='yes'){continue;}
  if(!seen[s(p.deal_id)]){throw new Error('ABORT: unexpected unsent row '+s(p.deal_id)+' '+s(p.investor)+' x '+s(p.startup)+' - state changed since review');}}

// ---- INVESTORS updates (all five resolve to exactly one existing row; never create) ----
function invRow(name){const h=inv.filter(r=>s(r.investor)===name);if(h.length!==1){throw new Error('ABORT: '+h.length+' INVESTORS rows named '+name);}
  if(s(h[0].do_not_contact).toLowerCase()==='yes'){throw new Error('ABORT: '+name+' is do_not_contact');}return h[0];}
for(const n of FIVE){invRow(n);}
function full(r,o){return Object.assign({investor:s(r.investor),contact_person:s(r.contact_person),email:s(r.email),sector:s(r.sector),stage:s(r.stage),cheque_inr_cr:s(r.cheque_inr_cr)},o);}
const invItems=[
 full(invRow('Siana Capital'),{sector:'B2B deep-tech business models; Deep-tech, IP-led innovation: HealthTech, Battery Tech, Biotech, MedTech'}),
 full(invRow('Prath Ventures'),{email:'ashna@prathventures.com',sector:'Consumer: consumer brands, consumer tech, allied services (may include manufacturing)',stage:'Seed, Pre-Series A, Series A'})];

// ---- one new match: DACBY x Prath Ventures (85) ----
const sr=st.filter(r=>nz(r.startup)==='dacby');
if(sr.length!==1){throw new Error('ABORT: '+sr.length+' STARTUPS rows for DACBY');}
if(s(sr[0].active).toLowerCase()!=='yes'){throw new Error('ABORT: DACBY not active');}
const owner=s(sr[0].owner);if(!owner){throw new Error('ABORT: DACBY has no owner');}
const firm={};const PE={'ria@prathventures.com':1,'ashna@prathventures.com':1};
for(const r of inv){if(nz(r.investor).indexOf('prathventur')===0){firm[nz(r.investor)]=1;}
  for(const e of s(r.email).toLowerCase().split(/[,;\s]+/)){if(PE[e]){firm[nz(r.investor)]=1;}}}
for(const p of pipe){if(firm[nz(p.investor)]&&nz(p.startup).indexOf('dacby')>=0){throw new Error('ABORT: DACBY already paired with Prath in PIPELINE ('+s(p.deal_id)+')');}}
for(const r of trk){if(nz(r[cInv]).indexOf('prathventur')!==0){continue;}if(nz(Object.values(r).join(' ')).indexOf('dacby')>=0){throw new Error('ABORT: Deal Tracker shows DACBY already with Prath');}}
let maxN=0;for(const p of pipe){const id=s(p.deal_id);if(id.charAt(0)==='D'){const v=parseInt(id.slice(1),10);if(!isNaN(v)&&v>maxN){maxN=v;}}}
if(maxN<4000){throw new Error('ABORT: max deal_id looks wrong: '+maxN);}
let pad=String(maxN+1);while(pad.length<5){pad='0'+pad;}
const newId='D'+pad;if(byId[newId]){throw new Error('ABORT: '+newId+' exists');}
const newRow={deal_id:newId,startup:s(sr[0].startup),owner:owner,investor:'Prath Ventures',email:'ashna@prathventures.com',cc:'',priority:85,deal_shared:'No',next_action:'Initial',next_due:'2026-09-15',notes:'Very High match (85)'};

// ---- ERROR LOG flags to resolve (Elevation Capital deliberately left open) ----
const FLAGS={
 'Riceberg Ventures':'No mandate change - Thesis tab holds a pass reply; record already foundational-AI-only. Deleted 21 off-mandate unsent rows added by the 10 Sep strict re-match.',
 'Siana Capital':'Sector now B2B deep-tech + IP-led health/battery/bio/medtech. Deleted 12 off-mandate unsent rows (10 Sep strict re-match). No new 70+ matches.',
 'DSG Consumer':'Alias: DSG Consumer = existing row DSG Consumer Partners. No thesis change (B2C only). Deleted 3 B2B unsent rows; paused Bon Cuisine follow-ups.',
 'Blinc invests':'Alias: Blinc invests = existing row Blinc Invest. Thesis-tab row is blank, nothing to apply. Deleted 3 tracker-duplicate + 2 off-mandate unsent rows; paused LUSTR follow-ups.',
 'Prath Ventures':'Email -> ashna@prathventures.com; sector consumer brands/tech/allied services; stage Seed-Series A. Deleted 8 unsent rows (6 off-mandate, 2 tracker duplicates), re-pointed 6 unsent rows to Ashna, added DACBY '+newId+'.'};
const fl=el.filter(r=>s(r.workflow)==='THESIS-WATCH'&&s(r.resolved)===''&&FLAGS[s(r.investor)]!==undefined);
if(fl.length!==5){throw new Error('ABORT: expected 5 open flags, found '+fl.length);}
const sf={};for(const r of fl){if(sf[s(r.investor)]){throw new Error('ABORT: two open flags for '+s(r.investor));}sf[s(r.investor)]=1;if(!r.row_number){throw new Error('ABORT: flag without row_number');}}
const hdr=((($('GET ERROR LOG header').first().json.values)||[])[0]||[]).map(x=>s(x).toLowerCase());
const ri=hdr.indexOf('resolved'),di=hdr.indexOf('details');
if(ri<0||di<0||ri>25||di>25||hdr.indexOf('workflow')<0||hdr.indexOf('investor')<0){throw new Error('ABORT: ERROR LOG header unexpected: '+JSON.stringify(hdr));}
const L=i=>String.fromCharCode(65+i);
const resolveBody={valueInputOption:'RAW',data:[]};
for(const r of fl){resolveBody.data.push({range:"'ERROR LOG'!"+L(ri)+r.row_number,values:[['Yes']]});
  resolveBody.data.push({range:"'ERROR LOG'!"+L(di)+r.row_number,values:[[(s(r.details)+' || RESOLVED 2026-09-10 re-match watch: '+FLAGS[s(r.investor)]).slice(0,1800)]]});}

// ---- atomic delete request (descending, applied in order by the Sheets API) ----
const shs=((($('GET pilot metadata').first().json.sheets)||[])).map(x=>x.properties);
const pl=shs.filter(p=>p.title==='PIPELINE');if(pl.length!==1){throw new Error('ABORT: PIPELINE tab not found');}
const body={requests:delItems.map(d=>({deleteDimension:{range:{sheetId:pl[0].sheetId,dimension:'ROWS',startIndex:d.row_number-1,endIndex:d.row_number}}}))};

return [{json:{body:body,del:delItems,pause:pauseItems,email:emailItems,inv:invItems,newRow:newRow,resolveBody:resolveBody,flags:fl.map(r=>({row_number:r.row_number,investor:s(r.investor)})),
 stats:{pipeline_before:pipe.length,tracker_rows:trk.length,tracker_distinct_investors:nDist,max_deal_before:maxN,trk_excluded:trkExcluded,pipeline_sheet_id:pl[0].sheetId,resolved_col:L(ri),details_col:L(di)}}}];

const r=$input.first().json;
if(!r||!Array.isArray(r.replies)||r.replies.length!==49){throw new Error('ABORT: delete batch returned '+JSON.stringify(r).slice(0,300));}
return $('Plan').first().json.inv.map(j=>({json:j}));

function s(v){return String(v==null?'':v).trim();}
const P=$('Plan').first().json;
const pipe=$('Read PIPELINE after').all().map(i=>i.json);
const inv=$('Read INVESTORS after').all().map(i=>i.json);
const el=$('Read ERROR LOG after').all().map(i=>i.json);
const ids={};for(const p of pipe){const id=s(p.deal_id);(ids[id]=ids[id]||[]).push(p);}
const out={pipeline_before:P.stats.pipeline_before,pipeline_after:pipe.length,expected_after:P.stats.pipeline_before-P.del.length+1,
 tracker_rows:P.stats.tracker_rows,tracker_distinct_investors:P.stats.tracker_distinct_investors,trk_excluded:P.stats.trk_excluded,max_deal_before:P.stats.max_deal_before};
out.deleted_still_present=P.del.filter(d=>ids[d.deal_id]).map(d=>d.deal_id);
out.pauses=P.pause.map(x=>{const r=(ids[x.deal_id]||[])[0];return x.deal_id+': pause='+(r?s(r.pause):'MISSING')+' next_action='+(r?s(r.next_action):'');});
out.emails=P.email.map(x=>{const r=(ids[x.deal_id]||[])[0];return x.deal_id+': '+(r?s(r.email):'MISSING');});
out.new_row=(ids[P.newRow.deal_id]||[]).map(r=>({row_number:r.row_number,deal_id:s(r.deal_id),startup:s(r.startup),investor:s(r.investor),email:s(r.email),owner:s(r.owner),priority:s(r.priority),next_due:s(r.next_due),next_action:s(r.next_action),deal_shared:s(r.deal_shared),notes:s(r.notes)}));
out.investors=inv.filter(r=>['Siana Capital','Prath Ventures'].indexOf(s(r.investor))>=0).map(r=>({row_number:r.row_number,investor:s(r.investor),contact_person:s(r.contact_person),email:s(r.email),sector:s(r.sector),stage:s(r.stage),cheque:s(r.cheque_inr_cr)}));
out.thesis_flags=el.filter(r=>s(r.workflow)==='THESIS-WATCH'&&(s(r.resolved)===''||s(r.timestamp)==='2026-09-10')).map(r=>({row_number:r.row_number,timestamp:s(r.timestamp),investor:s(r.investor),resolved:s(r.resolved)}));
const unresolvedFive=out.thesis_flags.filter(f=>f.resolved===''&&f.investor!=='Elevation Capital');
out.ok=out.pipeline_after===out.expected_after&&out.deleted_still_present.length===0&&out.new_row.length===1&&
 out.pauses.every(x=>x.indexOf('pause=Yes')>=0)&&out.emails.every(x=>x.indexOf('ashna@prathventures.com')>=0)&&unresolvedFive.length===0;
return [{json:out}];
